/**
 * Counts the election and returns `{ rounds, winner }`. `rounds` is a list
 * of `{ votes, exhausted, eliminated }`, where `votes` is a Map from
 * candidate name to BigInt vote count for every candidate still continuing
 * at that round, `exhausted` is the BigInt count of ballots that counted for
 * nobody, and `eliminated` is the name removed after the round or `null`
 * when the round ended the election. `winner` is the winning name or `null`.
 */
export function runElection(election) {
  const { candidates, ballots } = election
  let continuing = new Set(candidates)
  const rounds = []
  const history = [] // parallel to rounds: Map(name -> votes) for that round
  let winner = null

  for (;;) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0n)
    let exhausted = 0n

    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        votes.set(choice, votes.get(choice) + ballot.count)
      }
    }

    let activeTotal = 0n
    for (const v of votes.values()) activeTotal += v

    history.push(votes)

    if (activeTotal === 0n) {
      rounds.push({ votes, exhausted, eliminated: null })
      break
    }

    let majority = null
    for (const [name, v] of votes) {
      if (v * 2n > activeTotal) {
        majority = name
        break
      }
    }

    if (majority !== null) {
      winner = majority
      rounds.push({ votes, exhausted, eliminated: null })
      break
    }

    const eliminated = pickEliminated(votes, history)
    rounds.push({ votes, exhausted, eliminated })
    continuing = new Set([...continuing].filter((name) => name !== eliminated))
  }

  return { rounds, winner }
}

/**
 * Picks the candidate to eliminate: the one with the fewest votes in the
 * current round, breaking ties by comparing earlier rounds from the first
 * one onwards, and finally by whose name sorts last by code point.
 */
function pickEliminated(votes, history) {
  let min = null
  for (const v of votes.values()) {
    if (min === null || v < min) min = v
  }
  let tied = [...votes.keys()].filter((name) => votes.get(name) === min)

  if (tied.length > 1) {
    let r = 0
